import { useState } from 'react';
import { JxButton, JxModal } from '@jinx-ui/react';

export interface DeleteProjectButtonProps {
  onConfirm: () => void;
  projectName?: string;
}

export default function DeleteProjectButton({ onConfirm, projectName }: DeleteProjectButtonProps) {
  const [open, setOpen] = useState(false);

  const confirm = () => {
    setOpen(false);
    onConfirm();
  };

  return (
    <>
      <JxButton variant="danger" onClick={() => setOpen(true)}>
        Удалить проект
      </JxButton>
      <JxModal
        open={open}
        onOpenChange={setOpen}
        intent="danger"
        title="Удалить проект?"
        message={
          projectName
            ? `Проект «${projectName}» и все его данные будут удалены безвозвратно. Действие нельзя отменить.`
            : 'Проект и все его данные будут удалены безвозвратно. Действие нельзя отменить.'
        }
      >
        <JxButton variant="ghost" onClick={() => setOpen(false)}>
          Отмена
        </JxButton>
        <JxButton variant="danger" onClick={confirm}>
          Удалить
        </JxButton>
      </JxModal>
    </>
  );
}

